const invoices = $input.all().map(i => i.json);
const sum = (f) => invoices.reduce((s, inv) => s + (Number(inv[f]) || 0), 0);
const byStatus = {};
for (const inv of invoices) byStatus[inv.status || 'UNKNOWN'] = (byStatus[inv.status || 'UNKNOWN'] || 0) + 1;
const rows = invoices.slice(0, 25).map(inv =>
  `<tr><td>${inv.invoiceNumber ?? inv.number ?? '-'}</td><td>${inv.status ?? '-'}</td><td style="text-align:right">${(Number(inv.totalGross ?? inv.grossAmount) || 0).toFixed(2)} €</td></tr>`).join('');
const html = `<h2>cashwerk – Daily Invoice Summary</h2>
<p><b>${invoices.length}</b> invoices · total <b>${sum('totalGross').toFixed(2)} €</b></p>
<p>${Object.entries(byStatus).map(([k,v]) => `${k}: ${v}`).join(' · ')}</p>
<table border="1" cellpadding="6" style="border-collapse:collapse"><tr><th>Number</th><th>Status</th><th>Gross</th></tr>${rows}</table>`;
return [{ json: { html, count: invoices.length } }];
